Boolean sensor_warning( Sensor sensor )
{
    if( sensor->status.is_disabled || sensor->status.is_bypassed  || sensor->status.warning_na ) return FALSE  ; 
	
	if( sensor->status.npc_warn_enable )
	{
		Boolean npc  = npc_status( sensor->npc_warn ) ;
		
		npc_hit( sensor->npc_warn ) ; 

		return !npc ; 
	};

	return TRUE ;
}

